'use client';
import { useEffect, useRef, useState, type CSSProperties } from 'react';
import { useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import { grainTile } from './grain';
import styles from './styles.module.css';

type Palette = 'Signal' | 'Moss' | 'Ochre' | 'Graphite';
type Params = { palette: Palette; drift: number; grain: number; fields: number };

/** Each preset is paper + ink + ONE accent, all theme tokens, so both themes (and the always-dark stage) follow. */
const PALETTES: Record<Palette, { accent: string; name: string }> = {
  Signal: { accent: 'var(--s3-signal, #bf2f09)', name: 'Signal' },
  Moss: { accent: 'var(--s3-accent-data, #0a6e4d)', name: 'Moss' },
  Ochre: { accent: 'var(--s3-accent-3d, #8a5a00)', name: 'Ochre' },
  Graphite: { accent: 'color-mix(in oklab, var(--s3-ink, #11110f) 78%, var(--s3-bg, #f3f0e8))', name: 'Graphite' },
};

/** Base drift periods (s) at drift = 1 — long and mutually prime-ish so the fields never visibly sync. */
const PERIODS = [47, 61, 73, 89];

export default function GrainGradientMesh({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const root = useRef<HTMLDivElement>(null);
  const [grain, setGrain] = useState('');
  const [offscreen, setOffscreen] = useState(false);
  const palette = PALETTES[params.palette] ?? PALETTES.Signal;
  const drifting = !reduced && params.drift > 0;
  const fields = Math.round(Math.min(4, Math.max(3, params.fields)));

  // Generated once per page (module cache), never per frame.
  useEffect(() => { setGrain(grainTile()); }, []);

  // CSS animations are cheap, but there is no reason to composite them while the hero is scrolled away.
  useEffect(() => {
    const el = root.current;
    if (!el || !drifting || typeof IntersectionObserver === 'undefined') return;
    const io = new IntersectionObserver(([e]) => setOffscreen(!e.isIntersecting));
    io.observe(el);
    return () => io.disconnect();
  }, [drifting]);

  const vars = {
    '--gg-accent': palette.accent,
    '--gg-grain': grain ? `url(${grain})` : 'none',
    '--gg-grain-opacity': String(params.grain),
    ...Object.fromEntries(PERIODS.map((p, i) => [`--gg-t${i}`, `${(p / Math.max(0.05, params.drift)).toFixed(1)}s`])),
  } as CSSProperties;

  return (
    <div
      ref={root}
      className={styles.root}
      style={vars}
      data-drift={drifting ? '' : undefined}
      data-paused={offscreen ? '' : undefined}
    >
      <div className={styles.mesh} aria-hidden="true">
        <span className={`${styles.field} ${styles.f0}`} />
        <span className={`${styles.field} ${styles.f1}`} />
        <span className={`${styles.field} ${styles.f2}`} />
        {fields === 4 ? <span className={`${styles.field} ${styles.f3}`} /> : null}
        <span className={styles.grain} />
      </div>

      <div className={styles.card}>
        <p className={styles.kicker}>Sample hero</p>
        <h2 className={styles.title}>Warm light, slowly mixed.</h2>
        <p className={styles.body}>
          {fields === 4 ? 'Four' : 'Three'} soft colour fields drift on the compositor over a paper ground. One grain tile, generated once, keeps the large gradients from banding.
        </p>
        <ul className={styles.swatches} aria-label="Palette">
          <li><span className={styles.chip} data-tone="paper" aria-hidden="true" />Paper</li>
          <li><span className={styles.chip} data-tone="ink" aria-hidden="true" />Ink</li>
          <li><span className={styles.chip} data-tone="accent" aria-hidden="true" />{palette.name}</li>
        </ul>
      </div>
    </div>
  );
}

/**
 * Film-grain tile: a small square of seeded, roughly Gaussian luminance noise rendered ONCE with canvas2d and kept
 * as a PNG data URL. Tiled with CSS and blended with `overlay`, mid-grey (128) leaves colours untouched while the
 * deviations add grain — and dither away the banding that large 8-bit gradients otherwise show.
 */
let cached: string | null = null;

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Returns the cached data URL (generated on first call). Empty string when canvas2d is unavailable. */
export function grainTile(size = 128): string {
  if (cached !== null) return cached;
  if (typeof document === 'undefined') return '';
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) { cached = ''; return cached; }
  const img = ctx.createImageData(size, size);
  const rnd = mulberry32(0x5eed);
  for (let i = 0; i < img.data.length; i += 4) {
    // Sum of three uniforms ≈ Gaussian, σ ≈ 35 levels around mid-grey.
    const v = 128 + (rnd() + rnd() + rnd() - 1.5) * 70;
    const c = v < 0 ? 0 : v > 255 ? 255 : v;
    img.data[i] = img.data[i + 1] = img.data[i + 2] = c;
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  cached = canvas.toDataURL('image/png');
  return cached;
}

.root {
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  align-self: stretch;
  justify-self: stretch;
  min-height: 400px;
  display: grid;
  align-content: end;
  padding: clamp(16px, 4.5cqi, 40px);
  overflow: hidden;
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  color: var(--s3-ink, #11110f);
  background: var(--s3-bg, #f3f0e8);
  --gg-paper: var(--s3-bg, #f3f0e8);
  --gg-ink: var(--s3-ink, #11110f);
}

/* The mesh is its own stacking context, so it carries the paper: the grain must blend onto it, not onto nothing. */
.mesh { position: absolute; inset: 0; z-index: 0; pointer-events: none; background: var(--gg-paper); }

/* A colour field: one radial gradient with an eased falloff (no filter: blur — nothing to re-rasterise). */
.field {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: max(72cqi, 440px);
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(
    closest-side,
    var(--c) 0%,
    color-mix(in oklab, var(--c) 82%, transparent) 22%,
    color-mix(in oklab, var(--c) 52%, transparent) 46%,
    color-mix(in oklab, var(--c) 22%, transparent) 70%,
    color-mix(in oklab, var(--c) 6%, transparent) 88%,
    transparent 100%
  );
  transform: translate(-50%, -50%) rotate(var(--r, 0deg)) scale(var(--sx, 1), var(--sy, 1));
}
.f0 { --c: var(--gg-accent); --x: 12%; --y: 20%; --r: -8deg; --sx: 1.3; --sy: 0.9; }
.f1 { --c: color-mix(in oklab, var(--gg-accent) 72%, var(--gg-ink)); --x: 96%; --y: 52%; --r: 18deg; --sx: 0.72; --sy: 1.05; }
.f2 { --c: color-mix(in oklab, var(--gg-accent) 46%, var(--gg-paper)); --x: 70%; --y: 104%; --r: -16deg; --sx: 1.35; --sy: 0.82; }
.f3 { --c: color-mix(in oklab, var(--gg-accent) 12%, var(--gg-paper)); --x: 62%; --y: 6%; --r: 6deg; --sx: 1.2; --sy: 0.78; }

.grain {
  position: absolute;
  inset: 0;
  background-image: var(--gg-grain);
  background-size: 128px 128px;
  mix-blend-mode: overlay;
  opacity: var(--gg-grain-opacity, 0.3);
}

/* Drift: very slow, compositor-only transforms. Only when JS says so AND the OS allows motion. */
@media (prefers-reduced-motion: no-preference) {
  .root[data-drift] .field {
    will-change: transform;
    animation-timing-function: var(--s3-ease-inOut, cubic-bezier(0.65, 0, 0.35, 1));
    animation-iteration-count: infinite;
    animation-direction: alternate;
    animation-fill-mode: both;
  }
  .root[data-drift] .f0 { animation-name: drift0; animation-duration: var(--gg-t0); animation-delay: -13s; }
  .root[data-drift] .f1 { animation-name: drift1; animation-duration: var(--gg-t1); animation-delay: -29s; }
  .root[data-drift] .f2 { animation-name: drift2; animation-duration: var(--gg-t2); animation-delay: -7s; }
  .root[data-drift] .f3 { animation-name: drift3; animation-duration: var(--gg-t3); animation-delay: -41s; }
  .root[data-paused] .field { animation-play-state: paused; }
}
@keyframes drift0 {
  from { transform: translate(-50%, -50%) translate(-4cqi, -3cqi) rotate(-16deg) scale(1.22, 0.86); }
  to { transform: translate(-50%, -50%) translate(8cqi, 6cqi) rotate(4deg) scale(1.4, 0.96); }
}
@keyframes drift1 {
  from { transform: translate(-50%, -50%) translate(3cqi, -6cqi) rotate(26deg) scale(0.68, 1); }
  to { transform: translate(-50%, -50%) translate(-9cqi, 8cqi) rotate(6deg) scale(0.82, 1.14); }
}
@keyframes drift2 {
  from { transform: translate(-50%, -50%) translate(6cqi, 3cqi) rotate(-22deg) scale(1.3, 0.78); }
  to { transform: translate(-50%, -50%) translate(-12cqi, -5cqi) rotate(-4deg) scale(1.42, 0.9); }
}
@keyframes drift3 {
  from { transform: translate(-50%, -50%) translate(-7cqi, 2cqi) rotate(0deg) scale(1.12, 0.74); }
  to { transform: translate(-50%, -50%) translate(9cqi, 5cqi) rotate(16deg) scale(1.28, 0.86); }
}

.card {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 10px;
  width: min(31rem, 100%);
  padding: clamp(18px, 3.4cqi, 28px);
  background: var(--s3-surface, #fbf9f4);
  border: 1px solid var(--s3-line, #11110f24);
  border-radius: var(--s3-radius-m, 10px);
}
.kicker {
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--s3-ink-muted, #5c5a52);
}
.title {
  margin: 0;
  font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(1.75rem, 6.2cqi, 2.875rem);
  font-weight: 700;
  line-height: 0.98;
  letter-spacing: -0.035em;
  text-wrap: balance;
}
.body { margin: 0; max-width: 44ch; font-size: 0.9375rem; line-height: 1.5; color: var(--s3-ink-muted, #5c5a52); }
.swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  margin: 6px 0 0;
  padding: 0;
  list-style: none;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.swatches li { display: inline-flex; align-items: center; gap: 7px; }
.chip { width: 12px; height: 12px; border-radius: 50%; box-shadow: inset 0 0 0 1px var(--s3-line, #11110f24); }
.chip[data-tone='paper'] { background: var(--gg-paper); }
.chip[data-tone='ink'] { background: var(--gg-ink); }
.chip[data-tone='accent'] { background: var(--gg-accent); }
